from __future__ import absolute_import
from selenium.webdriver.common.by import By
from taf.ul.oam.selenium_coam.common.common import LocalBasicPage
from selenium.common.exceptions import TimeoutException


class BtsBasicInfo(LocalBasicPage):
    """
    The class corresponding to BTS basic info on selenium_coam web,
    all operations of BTS basic info will be implemented or added in it.
    """
    _STATUS_BAR_MENU_BUTTON = '//button[@class="btn minimal-button compact-button dropdown' \
                              '-toggle status-bar-menu-button"]'
    _STATUS_BAR_MENU_BUTTON_ELIPSIS = _STATUS_BAR_MENU_BUTTON + '/i'
    _CONNECT_DISCONNECT_BUTTON_XPATH = '//button[@aria-label="Connect Button"]'
    _CONNECT_DISCONNECT_DROPDOWN_LIST_BUTTON_XPATH = '//div[@class="status-bar-menu open"]/ul/li[1]/connection/a'
    _BTS_ID_XPATH = '//*[text()="BTS ID:"]/following-sibling::*[contains(@ng-mouseenter, ' \
                    '"attachTooltipWhenTruncatedText($event)")]'

    def check_activate_plan_status(self):
        activate_plan_status_xpath = "//div[contains(@class, 'status-text')]/span"
        self.get_text_by_xpath(activate_plan_status_xpath)

    def get_bts_id(self):
        return self.get_text_by_xpath(self._BTS_ID_XPATH)

    def get_bts_status(self):
        bts_status_xpath = '//div[contains(@class, "nbts-operational-state")]'
        return self.get_text_by_xpath(bts_status_xpath)

    def get_bts_version(self):
        bts_version_xpath = '//*[@aria-label="Software version"]'
        return self.get_text_by_xpath(bts_version_xpath)

    def connect_to_bts_if_disconnected(self, timeout):
        """
        Connects to BTS if Connect button is available and waits for successful connection
        :param timeout: time to wait for Connect/Disconnect button to be visible
        :type timeout: int
        """
        if self._check_status_bar_menu_button_type():
            self._reconnect_with_dropdown_list(timeout)
        else:
            self._reconnect_without_dropdown_list(timeout)

    def _can_be_connected_to_bts(self, dropdown_inside=False, timeout=5):
        """
        Checks in which state Connect/Disconnect button is in.
        :param dropdown_inside: tells if dropdown list exists in
        status bar menu as Connect/Disconnect button is placed in different
        position.
        :type dropdown_inside: bool
        :param timeout: time to wait for button state to be available
        :type timeout: int
        :return: True if button is in 'Connect' state, False otherwise
        :rtype: bool
        """
        if dropdown_inside:
            return self.driver.find_element_by_xpath(
                self._CONNECT_DISCONNECT_DROPDOWN_LIST_BUTTON_XPATH).text == 'Connect'
        return self.get_attribute_by_xpath(self._CONNECT_DISCONNECT_BUTTON_XPATH,
                                           'ui-tooltip', timeout) == 'Connect'

    def _check_status_bar_menu_button_type(self):
        """
        Checks the type of content of status bar menu button as it differs
        between 5G19A and 5G19B/Trunk (newer soft contains
        dropdown list inside).

        :return: True if status bar menu contains dropdown list, False otherwise
        :rtype: bool
        """
        try:
            self.wait_for_visibility_by_xpath(xpath=self._STATUS_BAR_MENU_BUTTON_ELIPSIS, timeout=5)
            return True
        except TimeoutException:
            return False

    def _reconnect_with_dropdown_list(self, timeout):
        """
        Reconnect with BTS by clicking connect (if it is disconnected),
        when status bar menu button contains dropdown list.
        :param timeout: Time to wait for particular steps being performed.
        :type timeout: int
        """
        self.wait_for_visibility_by_xpath(self._STATUS_BAR_MENU_BUTTON, timeout=10)
        self.click_enabled_element((By.XPATH, self._STATUS_BAR_MENU_BUTTON), timeout=10)
        if self._can_be_connected_to_bts(dropdown_inside=True):
            self.click_enabled_element((By.XPATH, self._CONNECT_DISCONNECT_DROPDOWN_LIST_BUTTON_XPATH), timeout=timeout)
            self.wait_for_text_not_present_in_element((By.XPATH, self._CONNECT_DISCONNECT_DROPDOWN_LIST_BUTTON_XPATH),
                                                      'Connect', timeout=timeout)

    def _reconnect_without_dropdown_list(self, timeout):
        """
        Reconnect with BTS by clicking connect (if it is disconnected),
        when status bar menu button does not contain dropdown list.
        :param timeout: Time to wait for particular steps being performed.
        :type timeout: int
        """
        self.wait_for_visibility_by_xpath(self._CONNECT_DISCONNECT_BUTTON_XPATH, timeout)
        if self._can_be_connected_to_bts():
            self.click_enabled_element((By.XPATH, self._CONNECT_DISCONNECT_BUTTON_XPATH), timeout=5)
        self.wait_for_text_not_present_in_element((By.XPATH, self._BTS_ID_XPATH), '---', timeout=30)
